const item = $input.first().json;
const headers = item.headers ?? {};
function isIpv4(value) { const parts = value.split('.'); return parts.length === 4 && parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) <= 255); }
function isIpv6(value) { if (!value.includes(':') || !/^[0-9a-f:]+$/i.test(value)) return false; if ((value.match(/::/g) || []).length > 1) return false; const parts = value.split(':'); const filled = parts.filter(Boolean); if (filled.some((part) => part.length > 4)) return false; return value.includes('::') ? filled.length <= 7 : filled.length === 8; }
const forwarded = headers['cf-connecting-ip'] || headers['x-real-ip'] || headers['x-forwarded-for'] || '';
const candidate = String(forwarded).split(',')[0].trim().replace(/^\[|\]$/g, '');
const ip = isIpv4(candidate) || isIpv6(candidate) ? candidate : 'unknown';
const dayKey = new Date().toISOString().slice(0, 10);
return [{ json: { ip, dayKey, systemKey: `system:${dayKey}`, ipKey: `ip:${dayKey}:${ip}` } }];

const row = $input.first().json;
const context = $('Build Quota Keys').first().json;
return [{ json: { ...context, systemUsed: Number(row.quota || 0) } }];

const row = $input.first().json;
const context = $('Normalize Status System').first().json;
const ipUsed = Number(row.quota || 0);
return [{ json: {
  ipLimit: 3, ipUsed, ipRemaining: Math.max(0, 3 - ipUsed),
  systemLimit: 12, systemUsed: context.systemUsed,
  systemRemaining: Math.max(0, 12 - context.systemUsed),
} }];
